WITH scored AS (SELECT *, ROUND(revenue / SUM(revenue) OVER (PARTITION BY store_id), 4) AS revenue_share, SUM(revenue) OVER (PARTITION BY store_id ORDER BY sale_date, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cumulative_revenue FROM store_sales) SELECT CASE WHEN revenue_share >= 0.67 THEN 'HIGH' ELSE 'LOW' END AS revenue_share_tier, COUNT(*) AS num_rows, BIT_AND(units) AS units_bit_and FROM scored GROUP BY CASE WHEN revenue_share >= 0.67 THEN 'HIGH' ELSE 'LOW' END ORDER BY units_bit_and DESC NULLS LAST
